std::pair<std::string,J> profile(int variant,int policy,int cap,P g,P partner,const std::vector<P>&source,const std::vector<P>&base){terminal_stop=variant==1;std::ostringstream out;out<<"FIELDALL "<<variant<<' '<<policy<<' '<<cap<<" 61 59 31\nBASE";for(P p:base){out<<' ';emit(p,out);}out<<'\n';Counts dc;std::vector<F>images;if(cap>=3)for(P p:base){images.push_back(*pairing(p,partner));dc.base_pairs++;}int rank_sum=0;
for(int qi=0;qi<31;qi++){out<<"DIAG "<<qi<<'\n';auto rows=query(source[qi],partner,base,images,cap,dc,out);Matrix m;for(auto row:rows)m.insert(row,0);if(qi)rank_sum+=m.a.size();out<<"RANK "<<m.a.size()<<'\n';}
int blocked=0,algebraic=0,identity=0;Counts total;total.peak=dc.peak;for(int qi=1;qi<31;qi++){auto r=recover_cold(source[qi],g,partner,base,cap);blocked+=r.kind==0;algebraic+=r.kind==1;identity+=r.kind==2;out<<"WORK "<<cap<<' '<<qi<<' ';emit(source[qi],out);out<<' '<<r.kind<<' '<<r.scalar<<' '<<r.rank<<' '<<r.setup_m<<' '<<r.shift;for(int x:r.logs)out<<' '<<x;auto c=r.count;out<<' '<<c.base_pairs<<' '<<c.query_pairs<<' '<<c.branches<<' '<<c.unknown<<' '<<c.certified<<' '<<c.root_checks<<' '<<c.rows<<' '<<c.setup_queries<<' '<<c.online_queries<<' '<<c.peak<<'\n'<<r.trace<<"END\n";total.base_pairs+=c.base_pairs;total.query_pairs+=c.query_pairs;total.branches+=c.branches;total.unknown+=c.unknown;total.certified+=c.certified;total.root_checks+=c.root_checks;total.rows+=c.rows;total.setup_queries+=c.setup_queries;total.online_queries+=c.online_queries;total.peak=std::max(total.peak,c.peak);}
out<<"CHECK 30 "<<blocked<<' '<<algebraic<<' '<<identity<<' '<<total.peak<<"\nMATRIX NA\n";J summary={{"variant",variant},{"policy",policy},{"cap",cap},{"uniform_initial_rank_numerator",rank_sum},{"rank_denominator",30},{"blocked_setups",blocked},{"algebraic_original_recoveries",algebraic},{"identity_shift_recoveries",identity},{"expanded_field_witness_peak",total.peak},{"base_pair_requests",total.base_pairs},{"query_pair_requests",total.query_pairs},{"setup_queries",total.setup_queries},{"online_queries",total.online_queries},{"unknown_branches",total.unknown},{"certified_branches",total.certified},{"base_root_evaluations",total.root_checks},{"ordered_rows",total.rows},{"diagnostic_base_pair_requests",dc.base_pairs},{"diagnostic_query_pair_requests",dc.query_pairs},{"diagnostic_unknown_branches",dc.unknown},{"diagnostic_certified_branches",dc.certified},{"matrix_degree",nullptr}};return{out.str(),summary};}
